templates.template:
{{ define "shopeasy.telegram.message" -}}
{{/* parse_mode HTML: todo texto variável passa por "html" (& < > soltos fazem o Telegram recusar a mensagem) */ -}}
{{ range .Alerts -}}
{{ if eq .Status "firing" }}{{ if eq .Labels.severity "critical" }}🔴{{ else }}🟠{{ end }} <b>ALERTA</b>{{ else }}✅ <b>RESOLVIDO</b>{{ end }} · <b>{{ .Labels.alertname | html }}</b>
{{ .Annotations.summary | html }}
{{ if eq .Status "firing" -}}
{{ .Annotations.description | html }}

<b>O que fazer:</b> {{ .Annotations.o_que_fazer | html }}
{{ end -}}
<i>severidade: {{ .Labels.severity | html }} · área: {{ .Labels.area | html }} · {{ .StartsAt.Local.Format "02/01 15:04" }}</i>
{{ if .PanelURL }}Painel: {{ .PanelURL | html }}{{ end }}

{{ end -}}
{{ end }}
